import json, struct, sys, zlib

HDR = 13  # u32 payload_length, u32 sequence, u8 kind, u32 transaction_id


def solve(req):
    pages = [bytearray(bytes.fromhex(p)) for p in req['pages']]
    checkpoint = req['checkpoint']
    log = bytes.fromhex(req['log'])
    n = len(log)
    active = {}  # transaction_id -> list of staged PATCH payload bytes
    valid = 0
    last_seq = 0
    pos = 0
    while pos + HDR <= n:
        plen, seq, kind, txid = struct.unpack_from('<IIBI', log, pos)
        if plen > 4096:
            break
        end = pos + HDR + plen + 4
        if end > n:
            break  # incomplete (torn) record
        if seq <= 0 or seq <= last_seq:
            break
        if txid == 0:
            break
        body = log[pos:pos + HDR + plen]
        crc = struct.unpack_from('<I', log, pos + HDR + plen)[0]
        if zlib.crc32(body) & 0xffffffff != crc:
            break
        # payload shape / bounds
        if kind in (1, 4):
            if plen != 0:
                break
        elif kind == 2:
            if plen < 6:
                break
            pi, off, cnt = struct.unpack_from('<HHH', log, pos + HDR)
            if cnt == 0 or plen != 6 + cnt:
                break
            if pi >= len(pages) or off + cnt > len(pages[pi]):
                break
        elif kind == 3:
            if plen != 8:
                break
        else:
            break  # unknown kind

        # structurally valid: apply semantics
        if kind == 1:  # BEGIN
            active[txid] = []
        elif kind == 2:  # PATCH
            if txid in active:
                active[txid].append(log[pos + HDR:pos + HDR + plen])
        elif kind == 4:  # ABORT
            active.pop(txid, None)
        else:  # COMMIT
            staged = active.pop(txid, None)
            if staged is not None:
                cnt, digest = struct.unpack_from('<II', log, pos + HDR)
                if (cnt == len(staged)
                        and digest == (zlib.crc32(b''.join(staged)) & 0xffffffff)
                        and seq > checkpoint):
                    for pl in staged:
                        pi, off, c = struct.unpack_from('<HHH', pl, 0)
                        pages[pi][off:off + c] = pl[6:6 + c]

        last_seq = seq
        valid = end
        pos = end
    return {'pages': [p.hex() for p in pages],
            'valid_bytes': valid,
            'last_seq': last_seq}


if __name__ == '__main__':
    out = sys.stdout
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        out.write(json.dumps(solve(json.loads(line))) + '\n')
    out.flush()
